REPLACE INTO `point_lang_data` (`id`, `point_id`, `language_id`, `title`, `data`) VALUES
	(1, 1, 1, 'Вилла Готланд', '{"desc": "<p>Новый отель Светлогорска, построенный в 2015 году, открывает свои радушные двери. &laquo;Скандинавский стиль&raquo; заслуживает особое внимание любителей неординарных интерьеров. Спокойные цвета, необычные, запоминающиеся элементы интерьера создают особый колорит.</p>\\r\\n\\r\\n<p>В отеле 12 двухместных комфортабельных номеров. В номерах телевизор, удобная мебель, сейф, мини-бар. Есть лоджия или &laquo;Французский балкон&raquo;. В ванной комнате есть душевая кабинка или ванна, фен.</p>\\r\\n\\r\\n<p>В наличии есть номер для лиц с ограниченными физическими возможностями.</p>\\r\\n\\r\\n<p>В отеле царит особая обстановка. Слышен шум моря, шелест листвы деревьев, окружающих отель. Прекрасное место отдыха в тишине.&nbsp;</p>\\r\\n\\r\\n<p>Рядом с отелем железнодорожная станция и автобусная остановка. Желающие могут приобрести курсовки на лечение в одном из близкорасположенных санаториев.</p>", "address": "ул. Ленина, д. 37", "short_desc": "<p>Мини-отель &quot;Вилла Готланд&quot; приглашает отдохнуть на берегу Балтийского моря.</p>"}'),
	(2, 1, 2, 'Villa Gotland', '{"desc": "<p>A new small hotel with Nordic style interior invites guests to the Baltic shore. The location of the hotel allows the visitors to walk to the centre of the town and to use funicular to go down to the promenade and city beach.</p>\\r\\n\\r\\n<p>There are 12 comfortable rooms with good furniture, TV, wi-fi.</p>\\r\\n\\r\\n<p>There is a room for physically challenged guests.</p>", "address": "37, Lenina str.", "short_desc": "<p>A small hotel invites to have a rest near to the Baltic see.</p>"}'),
	(3, 1, 3, 'Villa Gotland', '{"desc": "<p>Das Hotelgeb&auml;ude ist 2015 gebaut und liegt 100 Meter entfernt von der See in einer malerischen Umgebung unmittelbar am historischen Zentrum der Urlaubsort Svetlogorsk (vor 1946 Rauschen).</p>", "address": "Leninstrasse 37", "short_desc": "<p>Neues Mini-Hotel am Strand.</p>"}'),
	(4, 1, 4, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(5, 1, 5, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(6, 1, 6, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(7, 2, 1, 'Гостиница "Лазурь"', '{"desc": "<p>Гостиница &quot;Лазурь&quot; эконом класса, с размещением 128 человек. Последняя реконструкция была проведена в 2007 году. Гостям оказывается высокий сервис, в гостинице царит атмосфера домашнего уюта. Отдыхающие наслаждаются комфортными номерами со всеми удобствами. По утрам в кафе подаются вкусные завтраки.</p>\\r\\n\\r\\n<p>Нельзя не отметить удобное местоположение гостиницы. До пляжа расстояние 350 метров. Неподалеку находятся санатории &quot;Янтарь&quot; и &quot;Янтарный берег&quot;, в которых вы можете проходить оздоровительные процедуры. Для активного отдыха можно воспользоваться услугами С.О.К. &quot;Олимп&quot; - поплавать в открытом бассейне, или сыграть в большой теннис.&nbsp;</p>", "address": "Калининградский проспект, 70 Е", "short_desc": "<p>Гостиница находится в 350 метрах от пляжа. Здесь посетителям предоставляется высокое качество сервиса, в отеле царит атмосфера домашнего уюта.&nbsp;</p>"}'),
	(8, 2, 2, 'Hotel "Lazur" (Azure)', '{"desc": "<p>The hotel is 350 meters from the beach. Here, visitors are provided with high quality of service, at the homely comfort. Vacationers enjoy comfortable rooms for fair prices.</p>", "address": "70 E, Kaliningradskiy prospekt", "short_desc": "<p>The hotel is 350 meters from the beach. Here, visitors are provided with high quality of service, at the homely comfort.</p>"}'),
	(9, 2, 3, 'Hotel „Lasur“ (Bläue)', '{"desc": "<p>Das Hotel ist 350 Meter vom Strand entfernt. Hier werden die Besucher mit hoher Servicequalit&auml;t zur Verf&uuml;gung gestellt. Die G&auml;ste k&ouml;nnen den komfortablen Zimmern mit allen Annehmlichkeiten f&uuml;r einen vern&uuml;nftigen Preis genie&szlig;en.</p>", "address": "Kaliningradskiy prospekt 70 E", "short_desc": "<p>Das Hotel ist 350 Meter vom Strand entfernt. Hier werden die Besucher mit hoher Servicequalit&auml;t zur Verf&uuml;gung gestellt.&nbsp;</p>"}'),
	(10, 2, 4, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(11, 2, 5, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(12, 2, 6, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(13, 3, 1, 'Отель "Старый доктор"', '{"desc": "<p>В центре города Светлогорск в парковой зоне расположился уютный отель &quot;Старый Доктор&quot;. До моря можно добраться за 10 минут. Внимательный персонал, классический стиль гостиницы сделают ваш отдых приятным.</p>\\r\\n\\r\\n<p>В отеле есть 21 номер с паркетными полами, телевизором. Часть номеров включает в себя ванную комнату.</p>\\r\\n\\r\\n<p>Романтическое настроение создает&nbsp;кафе отеля, дизайн которого сделан&nbsp;в средневековом стиле. Интерьер кафе со входом в виде арки и печью-камином не оставят вас равнодушными.</p>\\r\\n\\r\\n<p>Для деловых людей предоставляется возможность организовать конференцию, семинар или тренинг в конференц-зале.&nbsp;</p>", "address": "ул. Юрия Гагарина, 12", "short_desc": "<p>В центре города Светлогорск в парковой зоне расположился этот уютный отель. Внимательный персонал, классический стиль гостиницы и&nbsp;оформленное в средневековом стиле кафе оставят самые теплые воспоминания об отдыхе на Балтийском море.</p>"}'),
	(14, 3, 2, '"Stariy Doctor" (The old doctor)', '{"desc": "<p>The attentive staff, the classic style of the hotel and cafe decorated in medieval style create unforgettable memories of the holiday on the Baltic Sea.</p>", "address": "12, Gagarina str.", "short_desc": "<p>The attentive staff, the classic style of the hotel and cafe decorated in medieval style create unforgettable memories of the holiday on the Baltic Sea.</p>"}'),
	(15, 3, 3, 'Hotel „Stariji Doktor“ (Alter Arzt)', '{"desc": "<p>Das Hotel liegt im Zentrum der Stadt Swetlogorsk im Parkgebiet. Das aufmerksame Personal, den klassischen Stil des Hotels werden die w&auml;rmsten Erinnerungen an den Urlaub an der Ostsee beibehalten.</p>", "address": "Gagarina strasse 12", "short_desc": "<p>Das Hotel liegt im Zentrum der Stadt Swetlogorsk im Parkgebiet.</p>"}'),
	(16, 3, 4, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(17, 3, 5, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(18, 3, 6, '', '{"desc": "", "address": "", "short_desc": ""}'),
	(19, 4, 1, 'Мини-гостиница "Из дома в дом"', '{"desc": "<p>Мини-гостиница &quot;Из дома в дом&quot; предлагает отдыхающим окунуться в спокойную атмосферу отдыха, где можно себя почувствовать не в гостинице, а в гостях у хороших друзей.</p>\\r\\n\\r\\n<p>Каждому гостю оказывается индивидуальный подход к его пожеланиям и предпочтениям отдыха. Здесь вы найдете домашнюю атмосферу и уютную обстановку, европейский уровень обслуживания.</p>\\r\\n\\r\\n<p>До побережья Балтийского моря вы можете пройти за 10 минут. Гостиница располагается на тихой улочке города, вокруг которой находятся современные особняки и загородные дома. Гостиница построена в 2007 году в виде блок-секции. Удобно посещать главный санаторий Светлогорска &quot;Янтарный берег&quot;, который находится в 300 метрах от гостиницы.</p>", "address": "ул. Архитектора Попова, 10 В", "short_desc": "<p>Предлагаем вам окунуться в спокойную атмосферу европейского комфорта в отеле, где можно себя почувствовать не в гостинице, а в гостях у хороших друзей. Персонал отеля оказывает индивидуальный подход каждому постояльцу.</p>"}'),
	(20, 4, 2, 'Mini-hotel "Iz doma v dom" (From door to door)', '{"desc": "", "address": "10 V, Arkhitektora Popova str.", "short_desc": ""}'),
	(21, 4, 3, '', '{"desc": "", "address": "", "short_desc": ""}'),
