	(128, 22, 2, 'Sports complex of Svetlogorsk military spa and health resort', '{"desc": "", "address": "22 A, Lenina str.", "short_desc": "<p>A swimming pool, a&nbsp;fitness center, a&nbsp;tennis court, volleyball and badminton fields in Svetlogorsk.</p>"}'),
